#!/bin/bash
# Replaces the "CONNECTED WALLET" section in SettingsScreen.kt to reflect Trust Wallet ONLY
sed -i 's/SettingsRow(title = "Wallet Address"/if (uiState.isWalletConnected) {\n                    SettingsRow(title = "Trust Wallet", subtitle = "Network: ${uiState.connectedNetwork}", trailingText = "${uiState.walletAddress.take(6)}••••${uiState.walletAddress.takeLast(4)}", onClick = { openModal("Trust Wallet Info") })\n                    SettingsRow(title = "Disconnect Wallet", onClick = { viewModel.disconnectWallet() }, textColor = MonetaCrimsonRed)\n                } else {\n                    SettingsRow(title = "Wallet Address", trailingText = "Not Connected", onClick = { openModal("Wallet Settings") })\n                }\n                \/\/ SettingsRow(title = "Wallet Address"/' app/src/main/java/com/example/ui/screens/SettingsScreen.kt
